43	int HostDataToTargetTy::addEventIfNecessary(DeviceTy &Device,
44	                                            AsyncInfoTy &AsyncInfo) const {
45	  // First, check if the user disabled atomic map transfer/malloc/dealloc.
46	  if (!MappingConfig::get().UseEventsForAtomicTransfers)
47	    return OFFLOAD_SUCCESS;
48	
49	  void *Event = getEvent();
50	  bool NeedNewEvent = Event == nullptr;
51	  if (NeedNewEvent && Device.createEvent(&Event) != OFFLOAD_SUCCESS) {
52	    REPORT() << "Failed to create event";
53	    return OFFLOAD_FAIL;
54	  }
55	
56	  // We cannot assume the event should not be nullptr because we don't
57	  // know if the target support event. But if a target doesn't,
58	  // recordEvent should always return success.
59	  if (Device.recordEvent(Event, AsyncInfo) != OFFLOAD_SUCCESS) {
60	    REPORT() << "Failed to set dependence on event " << Event;
61	    return OFFLOAD_FAIL;
62	  }
63	
64	  if (NeedNewEvent)
65	    setEvent(Event);
66	
67	  return OFFLOAD_SUCCESS;
68	}
69	
70	DeviceTy::DeviceTy(GenericPluginTy *RTL, int32_t DeviceID, int32_t RTLDeviceID)
71	    : DeviceID(DeviceID), RTL(RTL), RTLDeviceID(RTLDeviceID),
72	      MappingInfo(*this) {}
73	
74	DeviceTy::~DeviceTy() {
75	  if (DeviceID == -1 || !(getInfoLevel() & OMP_INFOTYPE_DUMP_TABLE))
76	    return;
77	
78	  ident_t Loc = {0, 0, 0, 0, ";libomptarget;libomptarget;0;0;;"};
79	  dumpTargetPointerMappings(&Loc, *this);
80	}
81	
82	llvm::Error DeviceTy::init() {
83	  int32_t Ret = RTL->init_device(RTLDeviceID);
84	  if (Ret != OFFLOAD_SUCCESS)
85	    return error::createOffloadError(error::ErrorCode::BACKEND_FAILURE,
86	                                     "failed to initialize device %d\n",
87	                                     DeviceID);
88	
89	  // Enables recording kernels if set.
90	  BoolEnvar OMPX_RecordKernel("LIBOMPTARGET_RECORD", false);
91	  if (OMPX_RecordKernel) {
92	    BoolEnvar OMPX_RecordOutput("LIBOMPTARGET_RECORD_OUTPUT", true);
93	    Int64Envar OMPX_RecordMemSize("LIBOMPTARGET_RECORD_MEMSIZE",
94	                                  8 * 1024 * 1024 * 1024ULL);
95	    Int32Envar OMPX_RecordDevice("LIBOMPTARGET_RECORD_DEVICE", 0);
96	    StringEnvar OMPX_RecordOutputDir("LIBOMPTARGET_RECORD_DIR", "");
97	    BoolEnvar OMPX_EmitRecordReport("LIBOMPTARGET_RECORD_REPORT", false);
98	    StringEnvar OMPX_RecordReportFilename("LIBOMPTARGET_RECORD_REPORT_FILENAME",
99	                                          "");
100	    if (OMPX_RecordDevice != RTLDeviceID)
101	      return llvm::Error::success();
102	
103	    // Print report if it was enabled explicitly or a report file was indicated.
104	    bool EmitReport =
105	        OMPX_EmitRecordReport || !OMPX_RecordReportFilename.get().empty();
106	
107	    Ret = RTL->initialize_record_replay(
108	        RTLDeviceID, OMPX_RecordMemSize, nullptr,
109	        /*IsRecord=*/true, /*IsNative=*/true, OMPX_RecordOutput, EmitReport,
110	        OMPX_RecordReportFilename.get().c_str(),
111	        OMPX_RecordOutputDir.get().c_str());
112	    if (Ret != OFFLOAD_SUCCESS)
113	      return error::createOffloadError(error::ErrorCode::BACKEND_FAILURE,
114	                                       "failed to initialize RR in device %d\n",
115	                                       DeviceID);
116	  }
117	
118	  return llvm::Error::success();
119	}
120	
121	// Extract the mapping of host function pointers to device function pointers
122	// from the entry table. Functions marked as 'indirect' in OpenMP will have
123	// offloading entries generated for them which map the host's function pointer
124	// to a global containing the corresponding function pointer on the device.
125	static llvm::Expected<std::pair<void *, uint64_t>>
126	setupIndirectCallTable(DeviceTy &Device, __tgt_device_image *Image,
127	                       __tgt_device_binary Binary) {
128	  AsyncInfoTy AsyncInfo(Device);
129	  llvm::ArrayRef<llvm::offloading::EntryTy> Entries(Image->EntriesBegin,
130	                                                    Image->EntriesEnd);
131	  llvm::SmallVector<std::pair<void *, void *>> IndirectCallTable;
132	  for (const auto &Entry : Entries) {
133	    if (Entry.Kind != llvm::object::OffloadKind::OFK_OpenMP ||
134	        Entry.Size == 0 ||
135	        (!(Entry.Flags & OMP_DECLARE_TARGET_INDIRECT) &&
136	         !(Entry.Flags & OMP_DECLARE_TARGET_INDIRECT_VTABLE)))
137	      continue;
138	
139	    size_t PtrSize = sizeof(void *);
140	    if (Entry.Flags & OMP_DECLARE_TARGET_INDIRECT_VTABLE) {
141	      // This is a VTable entry, the current entry is the first index of the
142	      // VTable and Entry.Size is the total size of the VTable. Unlike the
143	      // indirect function case below, the Global is not of size Entry.Size and
144	      // is instead of size PtrSize (sizeof(void*)).
145	      void *Vtable;
146	      void *res;
147	      if (Device.RTL->get_global(Binary, PtrSize, Entry.SymbolName, &Vtable))
148	        return error::createOffloadError(error::ErrorCode::INVALID_BINARY,
149	                                         "failed to load %s", Entry.SymbolName);
150	
151	      // HstPtr = Entry.Address;
152	      if (Device.retrieveData(&res, Vtable, PtrSize, AsyncInfo))
153	        return error::createOffloadError(error::ErrorCode::INVALID_BINARY,
154	                                         "failed to load %s", Entry.SymbolName);
155	      if (Device.synchronize(AsyncInfo))
156	        return error::createOffloadError(
157	            error::ErrorCode::INVALID_BINARY,
158	            "failed to synchronize after retrieving %s", Entry.SymbolName);
159	      // Calculate and emplace entire Vtable from first Vtable byte
160	      for (uint64_t i = 0; i < Entry.Size / PtrSize; ++i) {
161	        auto &[HstPtr, DevPtr] = IndirectCallTable.emplace_back();
162	        HstPtr = reinterpret_cast<void *>(
163	            reinterpret_cast<uintptr_t>(Entry.Address) + i * PtrSize);
164	        DevPtr = reinterpret_cast<void *>(reinterpret_cast<uintptr_t>(res) +
165	                                          i * PtrSize);
166	      }
167	    } else {
168	      // Indirect function case: Entry.Size should equal PtrSize since we're
169	      // dealing with a single function pointer (not a VTable)
170	      assert(Entry.Size == PtrSize && "Global not a function pointer?");
171	      auto &[HstPtr, DevPtr] = IndirectCallTable.emplace_back();
172	      void *Ptr;
173	      if (Device.RTL->get_global(Binary, Entry.Size, Entry.SymbolName, &Ptr))
174	        return error::createOffloadError(error::ErrorCode::INVALID_BINARY,
175	                                         "failed to load %s", Entry.SymbolName);
176	
177	      HstPtr = Entry.Address;
178	      if (Device.retrieveData(&DevPtr, Ptr, Entry.Size, AsyncInfo))
179	        return error::createOffloadError(error::ErrorCode::INVALID_BINARY,
180	                                         "failed to load %s", Entry.SymbolName);
181	    }
182	    if (Device.synchronize(AsyncInfo))
183	      return error::createOffloadError(
184	          error::ErrorCode::INVALID_BINARY,
185	          "failed to synchronize after retrieving %s", Entry.SymbolName);
186	  }
187	
188	  // If we do not have any indirect globals we exit early.
189	  if (IndirectCallTable.empty())
190	    return std::pair{nullptr, 0};
191	
192	  // Sort the array to allow for more efficient lookup of device pointers.
193	  llvm::sort(IndirectCallTable,
194	             [](const auto &x, const auto &y) { return x.first < y.first; });
195	
196	  uint64_t TableSize =
197	      IndirectCallTable.size() * sizeof(std::pair<void *, void *>);
198	  void *DevicePtr = Device.allocData(TableSize, nullptr, TARGET_ALLOC_DEVICE);
199	  if (Device.submitData(DevicePtr, IndirectCallTable.data(), TableSize,
200	                        AsyncInfo))
201	    return error::createOffloadError(error::ErrorCode::INVALID_BINARY,
202	                                     "failed to copy data");
203	  return std::pair<void *, uint64_t>(DevicePtr, IndirectCallTable.size());
204	}
205	
206	// Load binary to device and perform global initialization if needed.
207	llvm::Expected<__tgt_device_binary>
208	DeviceTy::loadBinary(__tgt_device_image *Img) {
209	  __tgt_device_binary Binary;
210	
211	  if (RTL->load_binary(RTLDeviceID, Img, &Binary) != OFFLOAD_SUCCESS)
212	    return error::createOffloadError(error::ErrorCode::INVALID_BINARY,
213	                                     "failed to load binary %p", Img);
214	
215	  // This symbol is optional.
216	  void *DeviceEnvironmentPtr;
217	  if (RTL->get_global(Binary, sizeof(DeviceEnvironmentTy),
218	                      "__omp_rtl_device_environment", &DeviceEnvironmentPtr))
219	    return Binary;
220	
221	  // Obtain a table mapping host function pointers to device function pointers.
222	  auto CallTablePairOrErr = setupIndirectCallTable(*this, Img, Binary);
223	  if (!CallTablePairOrErr)
224	    return CallTablePairOrErr.takeError();
225	
226	  GenericDeviceTy &GenericDevice = RTL->getDevice(RTLDeviceID);
227	  DeviceEnvironmentTy DeviceEnvironment;
228	  DeviceEnvironment.DeviceDebugKind = GenericDevice.getDebugKind();
229	  DeviceEnvironment.NumDevices = RTL->getNumDevices();
230	  // TODO: The device ID used here is not the real device ID used by OpenMP.
231	  DeviceEnvironment.DeviceNum = RTLDeviceID;
232	  DeviceEnvironment.DynamicMemSize = 0;
233	  DeviceEnvironment.ClockFrequency = GenericDevice.getClockFrequency();
234	  DeviceEnvironment.IndirectCallTable =
235	      reinterpret_cast<uintptr_t>(CallTablePairOrErr->first);
236	  DeviceEnvironment.IndirectCallTableSize = CallTablePairOrErr->second;
237	  DeviceEnvironment.HardwareParallelism =
238	      GenericDevice.getHardwareParallelism();
239	
240	  AsyncInfoTy AsyncInfo(*this);
241	  if (submitData(DeviceEnvironmentPtr, &DeviceEnvironment,
242	                 sizeof(DeviceEnvironment), AsyncInfo))
243	    return error::createOffloadError(error::ErrorCode::INVALID_BINARY,
244	                                     "failed to copy data");
245	
246	  return Binary;
247	}
