249	void *DeviceTy::allocData(int64_t Size, void *HstPtr, int32_t Kind) {
250	  /// RAII to establish tool anchors before and after data allocation
251	  void *TargetPtr = nullptr;
252	  OMPT_IF_BUILT(InterfaceRAII TargetDataAllocRAII(
253	                    RegionInterface.getCallbacks<ompt_target_data_alloc>(),
254	                    DeviceID, HstPtr, &TargetPtr, Size,
255	                    /*CodePtr=*/OMPT_GET_RETURN_ADDRESS);)
256	
257	  TargetPtr = RTL->data_alloc(RTLDeviceID, Size, HstPtr, Kind);
258	  return TargetPtr;
259	}
260	
261	int32_t DeviceTy::deleteData(void *TgtAllocBegin, int32_t Kind) {
262	  /// RAII to establish tool anchors before and after data deletion
263	  OMPT_IF_BUILT(InterfaceRAII TargetDataDeleteRAII(
264	                    RegionInterface.getCallbacks<ompt_target_data_delete>(),
265	                    DeviceID, TgtAllocBegin,
266	                    /*CodePtr=*/OMPT_GET_RETURN_ADDRESS);)
267	
268	  return RTL->data_delete(RTLDeviceID, TgtAllocBegin, Kind);
269	}
270	
271	// Submit data to device
272	int32_t DeviceTy::submitData(void *TgtPtrBegin, void *HstPtrBegin, int64_t Size,
273	                             AsyncInfoTy &AsyncInfo, HostDataToTargetTy *Entry,
274	                             MappingInfoTy::HDTTMapAccessorTy *HDTTMapPtr) {
275	  if (getInfoLevel() & OMP_INFOTYPE_DATA_TRANSFER)
276	    MappingInfo.printCopyInfo(TgtPtrBegin, HstPtrBegin, Size, /*H2D=*/true,
277	                              Entry, HDTTMapPtr);
278	
279	  /// RAII to establish tool anchors before and after data submit
280	  OMPT_IF_BUILT(
281	      InterfaceRAII TargetDataSubmitRAII(
282	          RegionInterface.getCallbacks<ompt_target_data_transfer_to_device>(),
283	          omp_initial_device, HstPtrBegin, DeviceID, TgtPtrBegin, Size,
284	          /*CodePtr=*/OMPT_GET_RETURN_ADDRESS);)
285	
286	  return RTL->data_submit_async(RTLDeviceID, TgtPtrBegin, HstPtrBegin, Size,
287	                                AsyncInfo);
288	}
289	
290	// Retrieve data from device
291	int32_t DeviceTy::retrieveData(void *HstPtrBegin, void *TgtPtrBegin,
292	                               int64_t Size, AsyncInfoTy &AsyncInfo,
293	                               HostDataToTargetTy *Entry,
294	                               MappingInfoTy::HDTTMapAccessorTy *HDTTMapPtr) {
295	  if (getInfoLevel() & OMP_INFOTYPE_DATA_TRANSFER)
296	    MappingInfo.printCopyInfo(TgtPtrBegin, HstPtrBegin, Size, /*H2D=*/false,
297	                              Entry, HDTTMapPtr);
298	
299	  /// RAII to establish tool anchors before and after data retrieval
300	  OMPT_IF_BUILT(
301	      InterfaceRAII TargetDataRetrieveRAII(
302	          RegionInterface.getCallbacks<ompt_target_data_transfer_from_device>(),
303	          DeviceID, TgtPtrBegin, omp_initial_device, HstPtrBegin, Size,
304	          /*CodePtr=*/OMPT_GET_RETURN_ADDRESS);)
305	
306	  return RTL->data_retrieve_async(RTLDeviceID, HstPtrBegin, TgtPtrBegin, Size,
307	                                  AsyncInfo);
308	}
309	
310	// Copy data from current device to destination device directly
311	int32_t DeviceTy::dataExchange(void *SrcPtr, DeviceTy &DstDev, void *DstPtr,
312	                               int64_t Size, AsyncInfoTy &AsyncInfo) {
313	  /// RAII to establish tool anchors before and after data exchange
314	  /// Note: Despite the fact that this is a data exchange, we use 'from_device'
315	  ///       operation enum (w.r.t. ompt_target_data_op_t) as there is currently
316	  ///       no better alternative. It is still possible to distinguish this
317	  ///       scenario from a real data retrieve by checking if both involved
318	  ///       device numbers are less than omp_get_num_devices().
319	  OMPT_IF_BUILT(
320	      InterfaceRAII TargetDataExchangeRAII(
321	          RegionInterface.getCallbacks<ompt_target_data_transfer_from_device>(),
322	          RTLDeviceID, SrcPtr, DstDev.RTLDeviceID, DstPtr, Size,
323	          /*CodePtr=*/OMPT_GET_RETURN_ADDRESS);)
324	  if (!AsyncInfo) {
325	    return RTL->data_exchange(RTLDeviceID, SrcPtr, DstDev.RTLDeviceID, DstPtr,
326	                              Size);
327	  }
328	  return RTL->data_exchange_async(RTLDeviceID, SrcPtr, DstDev.RTLDeviceID,
329	                                  DstPtr, Size, AsyncInfo);
330	}
331	
332	int32_t DeviceTy::dataFence(AsyncInfoTy &AsyncInfo) {
333	  return RTL->data_fence(RTLDeviceID, AsyncInfo);
334	}
335	
336	int32_t DeviceTy::notifyDataMapped(void *HstPtr, int64_t Size) {
337	  ODBG(ODT_Mapping) << "Notifying about new mapping: HstPtr=" << HstPtr
338	                    << ", Size=" << Size;
339	
340	  if (RTL->data_notify_mapped(RTLDeviceID, HstPtr, Size)) {
341	    REPORT() << "Notifying about data mapping failed.";
342	    return OFFLOAD_FAIL;
343	  }
344	  return OFFLOAD_SUCCESS;
345	}
346	
347	int32_t DeviceTy::notifyDataUnmapped(void *HstPtr) {
348	  ODBG(ODT_Mapping) << "Notifying about an unmapping: HstPtr=" << HstPtr;
349	
350	  if (RTL->data_notify_unmapped(RTLDeviceID, HstPtr)) {
351	    REPORT() << "Notifying about data unmapping failed.";
352	    return OFFLOAD_FAIL;
353	  }
354	  return OFFLOAD_SUCCESS;
355	}
356	
357	// Run region on device
358	int32_t DeviceTy::launchKernel(void *TgtEntryPtr, void **TgtVarsPtr,
359	                               ptrdiff_t *TgtOffsets, KernelArgsTy &KernelArgs,
360	                               KernelExtraArgsTy *KernelExtraArgs,
361	                               AsyncInfoTy &AsyncInfo) {
362	  return RTL->launch_kernel(RTLDeviceID, TgtEntryPtr, TgtVarsPtr, TgtOffsets,
363	                            &KernelArgs, KernelExtraArgs, AsyncInfo);
364	}
365	
366	// Run region on device
367	bool DeviceTy::printDeviceInfo() {
368	  RTL->print_device_info(RTLDeviceID);
369	  return true;
370	}
371	
372	// Whether data can be copied to DstDevice directly
373	bool DeviceTy::isDataExchangable(const DeviceTy &DstDevice) {
374	  if (RTL != DstDevice.RTL)
375	    return false;
376	
377	  if (RTL->is_data_exchangable(RTLDeviceID, DstDevice.RTLDeviceID))
378	    return true;
379	  return false;
