113	struct DeviceTy;
114	
115	/// The libomptarget wrapper around a __tgt_async_info object directly
116	/// associated with a libomptarget layer device. RAII semantics to avoid
117	/// mistakes.
118	class AsyncInfoTy {
119	public:
120	  enum class SyncTy { BLOCKING, NON_BLOCKING };
121	
122	private:
123	  /// Locations we used in (potentially) asynchronous calls which should live
124	  /// as long as this AsyncInfoTy object.
125	  std::deque<void *> BufferLocations;
126	
127	  /// Post-processing operations executed after a successful synchronization.
128	  /// \note the post-processing function should return OFFLOAD_SUCCESS or
129	  /// OFFLOAD_FAIL appropriately.
130	  using PostProcFuncTy = std::function<int()>;
131	  llvm::SmallVector<PostProcFuncTy> PostProcessingFunctions;
132	
133	  __tgt_async_info AsyncInfo;
134	  DeviceTy &Device;
135	
136	public:
137	  /// Synchronization method to be used.
138	  SyncTy SyncType;
139	
140	  AsyncInfoTy(DeviceTy &Device, SyncTy SyncType = SyncTy::BLOCKING)
141	      : Device(Device), SyncType(SyncType) {}
142	  ~AsyncInfoTy() { synchronize(); }
143	
144	  /// Implicit conversion to the __tgt_async_info which is used in the
145	  /// plugin interface.
146	  operator __tgt_async_info *() { return &AsyncInfo; }
147	
148	  /// Synchronize all pending actions.
149	  ///
150	  /// \note synchronization will be performance in a blocking or non-blocking
151	  /// manner, depending on the SyncType.
152	  ///
153	  /// \note if the operations are completed, the registered post-processing
154	  /// functions will be executed once and unregistered afterwards.
155	  ///
156	  /// \returns OFFLOAD_FAIL or OFFLOAD_SUCCESS appropriately.
157	  int synchronize();
158	
159	  /// Return a void* reference with a lifetime that is at least as long as this
160	  /// AsyncInfoTy object. The location can be used as intermediate buffer.
161	  void *&getVoidPtrLocation();
162	
163	  /// Check if all asynchronous operations are completed.
164	  ///
165	  /// \note only a lightweight check. If needed, use synchronize() to query the
166	  /// status of AsyncInfo before checking.
167	  ///
168	  /// \returns true if there is no pending asynchronous operations, false
169	  /// otherwise.
170	  bool isDone() const;
171	
172	  /// Add a new post-processing function to be executed after synchronization.
173	  ///
174	  /// \param[in] Function is a templated function (e.g., function pointers,
175	  /// lambdas, std::function) that can be convertible to a PostProcFuncTy (i.e.,
176	  /// it must have int() as its function signature).
177	  template <typename FuncTy> void addPostProcessingFunction(FuncTy &&Function) {
178	    static_assert(std::is_convertible_v<FuncTy, PostProcFuncTy>,
179	                  "Invalid post-processing function type. Please check "
180	                  "function signature!");
181	    PostProcessingFunctions.emplace_back(Function);
182	  }
183	
184	private:
185	  /// Run all the post-processing functions sequentially.
186	  ///
187	  /// \note after a successful execution, all previously registered functions
188	  /// are unregistered.
189	  ///
190	  /// \returns OFFLOAD_FAIL if any post-processing function failed,
191	  /// OFFLOAD_SUCCESS otherwise.
192	  int32_t runPostProcessing();
193	
194	  /// Check if the internal asynchronous info queue is empty or not.
195	  ///
196	  /// \returns true if empty, false otherwise.
197	  bool isQueueEmpty() const;
198	};
199	
200	// Wrapper for task stored async info objects.
201	class TaskAsyncInfoWrapperTy {
202	  // Invalid GTID as defined by libomp; keep in sync
203	  static constexpr int KMP_GTID_DNE = -2;
204	
205	  const int ExecThreadID = KMP_GTID_DNE;
206	  AsyncInfoTy LocalAsyncInfo;
207	  AsyncInfoTy *AsyncInfo = &LocalAsyncInfo;
208	  void **TaskAsyncInfoPtr = nullptr;
209	
210	public:
211	  TaskAsyncInfoWrapperTy(DeviceTy &Device)
212	      : ExecThreadID(__kmpc_global_thread_num(NULL)), LocalAsyncInfo(Device) {
213	    // If we failed to acquired the current global thread id, we cannot
214	    // re-enqueue the current task. Thus we should use the local blocking async
215	    // info.
216	    if (ExecThreadID == KMP_GTID_DNE)
217	      return;
218	
219	    // Only tasks with an assigned task team can be re-enqueue and thus can
220	    // use the non-blocking synchronization scheme. Thus we should use the local
221	    // blocking async info, if we don´t have one.
222	    if (!__kmpc_omp_has_task_team(ExecThreadID))
223	      return;
224	
225	    // Acquire a pointer to the AsyncInfo stored inside the current task being
226	    // executed.
227	    TaskAsyncInfoPtr = __kmpc_omp_get_target_async_handle_ptr(ExecThreadID);
228	
229	    // If we cannot acquire such pointer, fallback to using the local blocking
230	    // async info.
231	    if (!TaskAsyncInfoPtr)
232	      return;
233	
234	    // When creating a new task async info, the task handle must always be
235	    // invalid. We must never overwrite any task async handle and there should
236	    // never be any valid handle store inside the task at this point.
237	    assert((*TaskAsyncInfoPtr) == nullptr &&
238	           "Task async handle is not empty when dispatching new device "
239	           "operations. The handle was not cleared properly or "
240	           "__tgt_target_nowait_query should have been called!");
241	
242	    // If no valid async handle is present, a new AsyncInfo will be allocated
243	    // and stored in the current task.
244	    AsyncInfo = new AsyncInfoTy(Device, AsyncInfoTy::SyncTy::NON_BLOCKING);
245	    *TaskAsyncInfoPtr = (void *)AsyncInfo;
246	  }
247	
248	  ~TaskAsyncInfoWrapperTy() {
249	    // Local async info destruction is automatically handled by ~AsyncInfoTy.
250	    if (AsyncInfo == &LocalAsyncInfo)
251	      return;
252	
253	    // If the are device operations still pending, return immediately without
254	    // deallocating the handle.
255	    if (!AsyncInfo->isDone())
256	      return;
257	
258	    // Delete the handle and unset it from the OpenMP task data.
259	    delete AsyncInfo;
260	    *TaskAsyncInfoPtr = nullptr;
261	  }
262	
263	  operator AsyncInfoTy &() { return *AsyncInfo; }
